<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
require __DIR__.'/surf-beta-engine.php';
$pdo=cc_db();if(!$pdo){http_response_code(503);exit('Surf Match beta is temporarily unavailable.');}

$pdo->exec("CREATE TABLE IF NOT EXISTS surf_beta_subscribers (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 email VARCHAR(190) NOT NULL UNIQUE,
 confirmed TINYINT(1) NOT NULL DEFAULT 0,
 active TINYINT(1) NOT NULL DEFAULT 1,
 profile_json MEDIUMTEXT NOT NULL,
 email_frequency ENUM('morning','evening','both') NOT NULL DEFAULT 'morning',
 origin_lat DECIMAL(8,3) NULL,
 origin_lon DECIMAL(8,3) NULL,
 last_email_at DATETIME NULL,
 last_morning_date DATE NULL,
 last_evening_date DATE NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

function cc_beta_secret(): string {$c=cc_config();return hash('sha256','surf-beta-v2|'.($c['db_pass']??'fallback').'|costacams');}
function cc_beta_token(int $id,string $email,string $purpose): string {$sig=hash_hmac('sha256',$id.'|'.$purpose.'|'.strtolower($email),cc_beta_secret());return rtrim(strtr(base64_encode($id.'|'.$purpose.'|'.$sig),'+/','-_'),'=');}
function cc_beta_token_parse(string $token): ?array {$raw=base64_decode(strtr($token,'-_','+/'),true);if(!$raw)return null;$p=explode('|',$raw);if(count($p)!==3||!ctype_digit($p[0]))return null;return [(int)$p[0],$p[1],$p[2]];}
function cc_beta_valid_token(PDO $pdo,string $token,string $purpose): ?array {$p=cc_beta_token_parse($token);if(!$p||$p[1]!==$purpose)return null;$st=$pdo->prepare('SELECT * FROM surf_beta_subscribers WHERE id=? LIMIT 1');$st->execute([$p[0]]);$r=$st->fetch();if(!$r)return null;$exp=cc_beta_token((int)$r['id'],(string)$r['email'],$purpose);return hash_equals($exp,$token)?$r:null;}
function cc_beta_send_mail(string $to,string $subject,string $html): bool {$headers="MIME-Version: 1.0\r\nContent-type: text/html; charset=UTF-8\r\nFrom: CostaCams <support@costacams.com>\r\nReply-To: support@costacams.com\r\n";return @mail($to,$subject,$html,$headers);}

$base='https://costacams.com/ccdeploy-v3/costacams-v3/surf-match-beta-v2.php';
$status='';$managed=null;
if(isset($_GET['confirm'])){$r=cc_beta_valid_token($pdo,(string)$_GET['confirm'],'confirm');if($r){$pdo->prepare('UPDATE surf_beta_subscribers SET confirmed=1,active=1 WHERE id=?')->execute([(int)$r['id']]);$status='Email confirmed. Your Surf Brief subscription is active.';}else{$status='That confirmation link is invalid.';}}
if(isset($_GET['unsubscribe'])){$r=cc_beta_valid_token($pdo,(string)$_GET['unsubscribe'],'unsubscribe');if($r){$pdo->prepare('UPDATE surf_beta_subscribers SET active=0 WHERE id=?')->execute([(int)$r['id']]);$status='Surf Brief emails have been paused.';}else{$status='That unsubscribe link is invalid.';}}
if(isset($_GET['manage'])){$managed=cc_beta_valid_token($pdo,(string)$_GET['manage'],'manage');if(!$managed)$status='That manage-profile link is invalid.';}

if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='subscribe'){
 header('Content-Type: application/json; charset=utf-8');
 if(!empty($_POST['website'])){echo json_encode(['ok'=>true]);exit;}
 $email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Please enter a valid email.']);exit;}
 $profileRaw=(string)($_POST['profile']??'{}');$profile=json_decode($profileRaw,true);if(!is_array($profile))$profile=cc_surf_profile_defaults();
 $freq=in_array((string)($_POST['frequency']??'morning'),['morning','evening','both'],true)?(string)$_POST['frequency']:'morning';
 $olat=isset($profile['origin_lat'])&&is_numeric($profile['origin_lat'])?round((float)$profile['origin_lat'],3):null;$olon=isset($profile['origin_lon'])&&is_numeric($profile['origin_lon'])?round((float)$profile['origin_lon'],3):null;
 $sel=$pdo->prepare('SELECT * FROM surf_beta_subscribers WHERE email=? LIMIT 1');$sel->execute([$email]);$old=$sel->fetch();
 if($old && !empty($old['last_email_at']) && strtotime((string)$old['last_email_at'])>time()-240){echo json_encode(['ok'=>false,'message'=>'A link was sent recently. Please check your inbox.']);exit;}
 if($old){$id=(int)$old['id'];$pdo->prepare('UPDATE surf_beta_subscribers SET profile_json=?,email_frequency=?,origin_lat=?,origin_lon=?,active=1,last_email_at=NOW() WHERE id=?')->execute([json_encode($profile,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$freq,$olat,$olon,$id]);$confirmed=(bool)$old['confirmed'];}
 else{$pdo->prepare('INSERT INTO surf_beta_subscribers(email,profile_json,email_frequency,origin_lat,origin_lon,last_email_at) VALUES(?,?,?,?,?,NOW())')->execute([$email,json_encode($profile,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$freq,$olat,$olon]);$id=(int)$pdo->lastInsertId();$confirmed=false;}
 $confirm=$base.'?confirm='.rawurlencode(cc_beta_token($id,$email,'confirm'));$manage=$base.'?manage='.rawurlencode(cc_beta_token($id,$email,'manage'));$unsub=$base.'?unsubscribe='.rawurlencode(cc_beta_token($id,$email,'unsubscribe'));
 $subject=$confirmed?'Your CostaCams Surf Match profile':'Confirm your CostaCams Surf Brief';
 $body='<div style="font-family:Arial,sans-serif;max-width:620px;margin:auto;color:#172024"><h2>CostaCams Surf Brief</h2>'.($confirmed?'<p>Your Surf Match preferences were updated.</p>':'<p>Confirm your email to start receiving your requested surf brief.</p><p><a style="display:inline-block;padding:12px 18px;background:#0d6578;color:white;text-decoration:none;border-radius:8px" href="'.htmlspecialchars($confirm).'">Confirm Surf Brief</a></p>').'<p><a href="'.htmlspecialchars($manage).'">Manage your surf profile</a></p><p style="font-size:12px;color:#667">No password is required. Your private link manages your preferences.</p><p style="font-size:11px"><a href="'.htmlspecialchars($unsub).'">Unsubscribe</a></p></div>';
 $sent=cc_beta_send_mail($email,$subject,$body);
 echo json_encode(['ok'=>true,'confirmed'=>$confirmed,'mail_sent'=>$sent,'message'=>$confirmed?'Profile saved. We emailed your private manage link.':'Check your inbox and confirm your Surf Brief.']);exit;
}

$spots=cc_surf_load_spots($pdo);$dataset=json_encode($spots,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?:'[]';
$initial=cc_surf_profile_defaults();if($managed){$j=json_decode((string)$managed['profile_json'],true);if(is_array($j))$initial=array_replace($initial,$j);$initial['email']=(string)$managed['email'];$initial['email_frequency']=(string)$managed['email_frequency'];}
$initialJson=json_encode($initial,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?:'{}';
