<div class="research"><b>Why these inputs?</b> URBNSURF’s wave selector asks about recent surf frequency, experience, maximum wave height and regular board type. Published research also found surfer ability, wave size and wave period significantly associated with surfing performance. CostaCams adds wind, rain, UV, travel time and local spot context.</div>
</section></section></main><script src="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js"></script><script>
const spots=<?=$dataset?>;const initial=<?=$initialJson?>;let profile=Object.assign({mode:'simple',level:'competent',frequency:'few',board:'midlength',board_length:7,wave_target:.9,max_wave:1.2,power:'medium',handedness:'any',wind_tolerance:18,rain_tolerance:'prefer_dry',time_mode:'arrive',session_hour:17,day_offset:0,origin_lat:null,origin_lon:null},initial);let map,marker,routeLine,currentHls=null,ranked=[];
const $=id=>document.getElementById(id);const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));function fmtTime(v){let h=Math.floor(v),m=Math.round((v-h)*60);if(m===60){h++;m=0}const ap=h>=12?'PM':'AM';let hh=h%12;if(!hh)hh=12;return hh+':'+String(m).padStart(2,'0')+' '+ap}function ad(a,b){return Math.abs(((a-b+540)%360)-180)}function nearest(spot,epoch){let best=null,d=1e20;for(const h of spot.hours){const x=Math.abs(h.epoch-epoch);if(x<d){d=x;best=h}}return best}function hav(a,b,c,d){const R=6371,dr=x=>x*Math.PI/180,dl=dr(c-a),dn=dr(d-b),q=Math.sin(dl/2)**2+Math.cos(dr(a))*Math.cos(dr(c))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(q)))}function travelMin(s){if(profile.origin_lat==null||profile.origin_lon==null)return null;const km=hav(profile.origin_lat,profile.origin_lon,s.lat,s.lon)*1.28;return Math.max(5,Math.round(km/58*60+5))}
function selectedEpoch(){const now=new Date();const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()+Number(profile.day_offset||0),Math.floor(profile.session_hour),Math.round((profile.session_hour%1)*60),0);return Math.floor(d.getTime()/1000)}
function scoreSpot(s,h){let sc=72,re=[];const wave=Number(h.wave_height||0),per=Number(h.wave_period||0),wind=Number(h.wind_speed||0),rain=Number(h.rain_probability||0),energy=Number(h.energy_kwm||0),diff=Math.abs(wave-profile.wave_target);sc-=Math.min(34,diff*24);if(diff<.22){sc+=8;re.push('wave size fits you')}if(wave>profile.max_wave){sc-=Math.min(45,(wave-profile.max_wave)*35);re.push('above your comfort size')}if(profile.level==='learning'&&wave>1)sc-=18;if(profile.level==='learning'&&per>10)sc-=8;if(profile.level==='very_good'&&wave>=1)sc+=6;if(per>=10){sc+=10;re.push('well-spaced swell')}else if(per>=8)sc+=5;else if(per<6.5){sc-=10;re.push('waves closer together')}const ideal=profile.power==='soft'?1:(profile.power==='powerful'?5:2.5);sc-=Math.min(20,Math.abs(energy-ideal)*3.2);if(wind>profile.wind_tolerance){sc-=Math.min(28,(wind-profile.wind_tolerance)*1.7);re.push('wind stronger than preferred')}if(h.wind_direction!=null){const x=ad(Number(h.wind_direction),Number(s.offshore_from));if(x<45){sc+=10;re.push('offshore wind')}else if(x>120&&wind>8){sc-=10;re.push('more onshore wind')}}if(profile.handedness!=='any'&&s.handedness!=='both')sc+=s.handedness===profile.handedness?5:-6;if(['softboard','longboard'].includes(profile.board)&&wave<=1.1)sc+=7;if(profile.board==='shortboard'&&wave>=.7&&per>=7)sc+=6;return {score:Math.round(clamp(sc,0,100)),re:[...new Set(re)].slice(0,3)}}
function calculate(epoch=selectedEpoch()){const out=[];for(const s of spots){const tr=travelMin(s),evalEpoch=profile.time_mode==='leave'&&tr!=null?epoch+tr*60:epoch,h=nearest(s,evalEpoch);if(!h)continue;const z=scoreSpot(s,h);out.push({s,h,score:z.score,re:z.re,travel:tr,evalEpoch})}out.sort((a,b)=>b.score-a.score);return out}
function uvLabel(u){if(u<3)return['Low','UV below 3: sun protection is less urgent, but water reflection still matters.'];if(u<6)return['Moderate','Use SPF50+ broad-spectrum water-resistant sunscreen, rashie/UPF clothing and reapply after surfing.'];if(u<8)return['High','SPF50+ water-resistant sunscreen + rashie/UPF clothing. Limit unnecessary exposure and reapply after the water.'];if(u<11)return['Very High','Strong UV: SPF50+, UPF clothing, shade before/after the session and reapply after surfing.'];return['Extreme','Extreme UV: maximum sun protection; strongly limit unnecessary exposure around the session.']}
function periodFriendly(p){if(p<7)return['Waves close together','8px'];if(p<10)return['Moderately spaced waves','15px'];return['Well-spaced, more organised swell','26px']}
function refresh(){profile.time_mode=$('timeMode').value;profile.session_hour=Number($('time').value);profile.day_offset=Number($('day').value);profile.level=$('level').value;profile.board=$('board').value;profile.board_length=Number($('boardLen').value);profile.wave_target=Number($('wave').value);profile.max_wave=Number($('maxWave').value);profile.wind_tolerance=Number($('wind').value);$('timeLabel').textContent=fmtTime(profile.session_hour);$('boardLenOut').textContent=profile.board_length.toFixed(1).replace('.0','')+" ft";$('waveOut').textContent=profile.wave_target.toFixed(1)+' m';$('windOut').textContent=profile.wind_tolerance+' km/h';ranked=calculate();render()}
function render(){if(!ranked.length)return;const a=ranked[0];$('score').textContent=a.score;$('winnerName').textContent=a.s.name;$('winnerWhen').textContent=(profile.time_mode==='leave'?'If you leave at ':'For ')+fmtTime(profile.session_hour)+' · '+a.h.local;$('metrics').innerHTML=`<span class="metric">🌊 ${Number(a.h.wave_height||0).toFixed(1)} m</span><span class="metric">↔ ${Number(a.h.wave_period||0).toFixed(0)} s</span><span class="metric">⚡ ${Number(a.h.energy_kwm||0).toFixed(1)} kW/m</span><span class="metric">💨 ${a.h.wind_compass||'—'} ${Math.round(a.h.wind_speed||0)} km/h</span><span class="metric">🌧 ${Math.round(a.h.rain_probability||0)}%</span>`;const uv=Number(a.h.uv||0),u=uvLabel(uv);$('uvnum').textContent=uv.toFixed(1);$('uvlabel').textContent=u[0];$('uvtext').textContent=u[1];const pf=periodFriendly(Number(a.h.wave_period||0));$('resultPeriod').style.setProperty('--gap',pf[1]);$('resultPeriodText').textContent=pf[0]+` (${Number(a.h.wave_period||0).toFixed(0)} s in Advanced mode)`;$('periodDemo').style.setProperty('--gap',pf[1]);$('periodText').textContent=pf[0]+'. Longer spacing usually means more organised energy arriving at the coast.';renderTravel(a);$('rank').innerHTML=ranked.slice(1,4).map((x,i)=>`<div class="rankrow"><div>#${i+2}</div><div><b>${x.s.name}</b><small>${Number(x.h.wave_height||0).toFixed(1)} m · ${Math.round(x.h.wave_period||0)} s · ${x.h.wind_compass||'—'} ${Math.round(x.h.wind_speed||0)} km/h${x.travel!=null?' · ~'+x.travel+' min drive':''}</small></div><div class="rankscore">${x.score}</div></div>`).join('');renderTimeline();renderMap(a);renderCamera(a)}
function renderTravel(a){if(a.travel==null){$('travel').innerHTML='<span class="sub">Set your location to calculate travel and departure time.</span>';return}const mins=a.travel;if(profile.time_mode==='arrive'){const t=new Date(selectedEpoch()*1000-mins*60000);$('travel').innerHTML=`<strong>Leave about ${t.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</strong><span class="sub">Estimated drive ~${mins} min to be there at ${fmtTime(profile.session_hour)}.</span>`}else{const t=new Date(selectedEpoch()*1000+mins*60000);$('travel').innerHTML=`<strong>Arrive about ${t.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</strong><span class="sub">Estimated drive ~${mins} min. Conditions are scored for your estimated arrival time.</span>`}routeWinner(a)}
function renderTimeline(){const times=[6,8,10,12,14,16,18];$('timeline').innerHTML=times.map(t=>{const old=profile.session_hour;profile.session_hour=t;const r=calculate(selectedEpoch())[0];profile.session_hour=old;if(!r)return'';return `<div class="slot"><small>${fmtTime(t)}</small><b>${r.s.name}</b><div class="s">${r.score}</div><small>${Number(r.h.wave_height||0).toFixed(1)}m · ${Math.round(r.h.wave_period||0)}s</small></div>`}).join('')}
function initMap(){map=L.map('spotMap',{zoomControl:true,scrollWheelZoom:false}).setView([-28.2,153.53],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap'}).addTo(map)}function renderMap(a){if(!map)initMap();if(marker)marker.remove();marker=L.marker([a.s.lat,a.s.lon]).addTo(map).bindPopup(a.s.name);map.setView([a.s.lat,a.s.lon],12);setTimeout(()=>map.invalidateSize(),50)}async function routeWinner(a){if(profile.origin_lat==null||profile.origin_lon==null||!map)return;try{const u=`https://router.project-osrm.org/route/v1/driving/${profile.origin_lon},${profile.origin_lat};${a.s.lon},${a.s.lat}?overview=full&geometries=geojson`;const r=await fetch(u);const j=await r.json();if(!j.routes||!j.routes[0])return;const rt=j.routes[0],mins=Math.round(rt.duration/60);if(routeLine)routeLine.remove();routeLine=L.geoJSON(rt.geometry,{interactive:false}).addTo(map);map.fitBounds(routeLine.getBounds().pad(.12));if(profile.time_mode==='arrive'){const t=new Date(selectedEpoch()*1000-mins*60000);$('travel').innerHTML=`<strong>Leave about ${t.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</strong><span class="sub">Route estimate ${mins} min · ${(rt.distance/1000).toFixed(0)} km.</span>`}else{const t=new Date(selectedEpoch()*1000+mins*60000);$('travel').innerHTML=`<strong>Arrive about ${t.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</strong><span class="sub">Route estimate ${mins} min · ${(rt.distance/1000).toFixed(0)} km.</span>`}}catch(e){}}
function renderCamera(a){if(currentHls){try{currentHls.destroy()}catch(e){}currentHls=null}const box=$('camPreview'),c=a.s.camera;box.innerHTML='';if(!c){box.textContent='No embeddable live camera is available for this beach yet.';return}if(c.type==='iframe'){const f=document.createElement('iframe');f.src=c.url;f.allow='autoplay; fullscreen';f.allowFullscreen=true;f.loading='lazy';box.appendChild(f);return}const v=document.createElement('video');v.muted=true;v.autoplay=true;v.playsInline=true;v.controls=true;v.preload='metadata';box.appendChild(v);if(v.canPlayType('application/vnd.apple.mpegurl')){v.src=c.url;v.play().catch(()=>{});return}const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/hls.js@latest';s.async=true;s.onload=()=>{if(window.Hls&&Hls.isSupported()){currentHls=new Hls({enableWorker:true,maxBufferLength:10});currentHls.loadSource(c.url);currentHls.attachMedia(v);currentHls.on(Hls.Events.MANIFEST_PARSED,()=>v.play().catch(()=>{}));}};document.head.appendChild(s)}
function bindSeg(id,key){document.querySelectorAll('#'+id+' button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#'+id+' button').forEach(x=>x.classList.remove('active'));b.classList.add('active');profile[key]=b.dataset.v;refresh()}))}bindSeg('power','power');bindSeg('hand','handedness');document.querySelectorAll('.quick button').forEach(b=>b.addEventListener('click',()=>{let v=b.dataset.time;if(v==='now'){const n=new Date();v=n.getHours()+Math.round(n.getMinutes()/30)*.5} $('time').value=clamp(Number(v),5,19);refresh()}));document.querySelectorAll('.wave-choice').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.wave-choice').forEach(x=>x.classList.remove('active'));b.classList.add('active');profile.wave_target=Number(b.dataset.wave);profile.max_wave=Number(b.dataset.max);$('wave').value=profile.wave_target;$('maxWave').value=profile.max_wave;$('waveFriendly').textContent=b.querySelector('small').textContent+'-style comfort';refresh()}));
$('simpleMode').onclick=()=>{$('mixer').classList.remove('advanced');$('simpleMode').classList.add('active');$('advancedMode').classList.remove('active');profile.mode='simple'};$('advancedMode').onclick=()=>{$('mixer').classList.add('advanced');$('advancedMode').classList.add('active');$('simpleMode').classList.remove('active');profile.mode='advanced'};['timeMode','time','day','level','board','boardLen','wave','maxWave','wind'].forEach(id=>$(id).addEventListener('input',refresh));
$('useLocation').onclick=()=>{if(!navigator.geolocation){$('locationState').textContent='Location is not supported in this browser.';return}$('locationState').textContent='Requesting location permission…';navigator.geolocation.getCurrentPosition(pos=>{profile.origin_lat=Number(pos.coords.latitude.toFixed(5));profile.origin_lon=Number(pos.coords.longitude.toFixed(5));$('locationState').textContent='Location set. No address was requested. Travel time now affects recommendations.';refresh()},()=>{$('locationState').textContent='Location permission was not granted. You can keep using Surf Match without travel estimates.'},{enableHighAccuracy:false,timeout:8000,maximumAge:300000})};
$('subscribeBtn').onclick=async()=>{const email=$('email').value.trim();if(!email){$('emailMsg').textContent='Enter your email first.';return}const p=Object.assign({},profile);if(!$('saveLocation').checked){p.origin_lat=null;p.origin_lon=null}const body=new URLSearchParams({action:'subscribe',email,profile:JSON.stringify(p),frequency:$('frequency').value,website:$('website').value});$('emailMsg').textContent='Saving…';try{const r=await fetch(location.pathname,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const j=await r.json();$('emailMsg').textContent=j.message||'Saved.'}catch(e){$('emailMsg').textContent='Could not save the profile right now.'}};
function applyInitial(){if(initial.email)$('email').value=initial.email;if(initial.email_frequency)$('frequency').value=initial.email_frequency;['time_mode','level','board'].forEach(k=>{const el=$(k==='time_mode'?'timeMode':k);if(el&&initial[k]!=null)el.value=initial[k]});$('time').value=initial.session_hour??17;$('day').value=initial.day_offset??0;$('boardLen').value=initial.board_length??7;$('wave').value=initial.wave_target??.9;$('maxWave').value=initial.max_wave??1.2;$('wind').value=initial.wind_tolerance??18;if(initial.origin_lat!=null&&initial.origin_lon!=null){profile.origin_lat=Number(initial.origin_lat);profile.origin_lon=Number(initial.origin_lon);$('locationState').textContent='Approximate saved location loaded from your profile.'}if(initial.mode==='advanced')$('advancedMode').click();refresh()}applyInitial();
</script></body></html>